ee:variables.ee:set-variable:
%dw 2.0 output application/java
// --- CUSTOM NORMALIZATION FUNCTION --- fun normalizeAddress(addressString: String) = do { var lowerCaseAddr = lower(addressString default "") var noPunctuation = lowerCaseAddr replace /[^a-z0-9\s]/ with ""
var abbreviated = noPunctuation replace /\bsuite\b/ with "ste" replace /\bapartment\b/ with "apt" replace /\bbuilding\b/ with "bldg" replace /\bfloor\b/ with "fl" replace /\broom\b/ with "rm" replace /\bnortheast\b/ with "ne" replace /\bnorthwest\b/ with "nw" replace /\bsoutheast\b/ with "se" replace /\bsouthwest\b/ with "sw" replace /\bnorth\b/ with "n" replace /\bsouth\b/ with "s" replace /\beast\b/ with "e" replace /\bwest\b/ with "w" replace /\bavenue\b/ with "ave" replace /\bstreet\b/ with "st" replace /\bboulevard\b/ with "blvd" replace /\bplace\b/ with "pl" replace /\bhighway\b/ with "hwy" replace /\bcanyon\b/ with "cyn" replace /\bcenter\b/ with "ctr" replace /\bcircle\b/ with "cir" replace /\bdrive\b/ with "dr" replace /\blane\b/ with "ln" replace /\bmountain\b/ with "mtn" replace /\broad\b/ with "rd" replace /\bcourt\b/ with "ct" replace /\bbroadway\b/ with "brdway" replace /\bparkway\b/ with "pkwy" replace /\bturnpike\b/ with "tpke" replace /\bmeadow\b/ with "mdw"
var fullyNormalized = abbreviated replace /\s/ with ""
--- fullyNormalized }
// Combine Address 1 and Address 2 var rawAddress = (vars.originalPayload.shipping_address.address1 default "") ++ " " ++ (vars.originalPayload.shipping_address.address2 default "")
// Format the Zip Code var zipCode = if (vars.originalPayload.shipping_address.country_code == "CA") (vars.originalPayload.shipping_address.zip default "") replace /\s/ with "" else (vars.originalPayload.shipping_address.zip default "")
--- normalizeAddress(rawAddress) ++ zipCode

ee:message.ee:set-payload:
%dw 2.0 output application/java var addressList = payload.value default payload
fun normalize(addressString: String) = do { var lowerCaseAddr = lower(addressString default "") var noPunctuation = lowerCaseAddr replace /[^a-z0-9\s]/ with "" var abbreviated = noPunctuation replace /\bsuite\b/ with "ste" replace /\bapartment\b/ with "apt" replace /\bbuilding\b/ with "bldg" replace /\bfloor\b/ with "fl" replace /\broom\b/ with "rm" replace /\bnortheast\b/ with "ne" replace /\bnorthwest\b/ with "nw" replace /\bsoutheast\b/ with "se" replace /\bsouthwest\b/ with "sw" replace /\bnorth\b/ with "n" replace /\bsouth\b/ with "s" replace /\beast\b/ with "e" replace /\bwest\b/ with "w" replace /\bavenue\b/ with "ave" replace /\bstreet\b/ with "st" replace /\bboulevard\b/ with "blvd" replace /\bplace\b/ with "pl" replace /\bhighway\b/ with "hwy" replace /\bcanyon\b/ with "cyn" replace /\bcenter\b/ with "ctr" replace /\bcircle\b/ with "cir" replace /\bdrive\b/ with "dr" replace /\blane\b/ with "ln" replace /\bmountain\b/ with "mtn" replace /\broad\b/ with "rd" replace /\bcourt\b/ with "ct" replace /\bbroadway\b/ with "brdway" replace /\bparkway\b/ with "pkwy" replace /\bturnpike\b/ with "tpke" replace /\bmeadow\b/ with "mdw"
--- abbreviated replace /\s/ with "" }
// Check ONLY Delivery Address AND ensure the account is active (Not On Hold) var matchedRecords = addressList filter ((address) -> (address.OnHoldStatus default "No") == "No" and normalize((address.AddressStreet default "") ++ " " ++ (address.AddressZipCode default "")) == vars.normalizedShipping ) --- (matchedRecords map $.CustomerAccount default []) distinctBy $

%dw 2.0
output application/java

var tags = (vars.originalPayload.tags default "") ++ (vars.originalPayload.customer.tags default "")
var gateway = lower(vars.originalPayload.payment_gateway_names[0] default "")

var isNet30 = contains(lower(tags), "net 30")
var paymentMethod = if (isNet30) "PAYLINK" else if (gateway == "paypal") "PAYPAL" else "CCMANUAL"
var paymentTerms = if (isNet30) "NET30" else "SHOPIFY"

var shippingTitle = vars.originalPayload.shipping_lines[0].title default ""
var deliveryMode = if (contains(lower(shippingTitle), "ground")) "UPS - GND" 
                   else if (contains(lower(shippingTitle), "2nd day")) "UPS 2ND DAY" 
                   else ""

---
{
    "dataAreaId": "zyus",
    "OrderingCustomerAccountNumber": vars.selectedCustomerAccount,
//    "SalesOrderName": vars.originalPayload.id as String,
    "CurrencyCode": "USD",
    "LanguageId": "en-US",
    "CustomersOrderReference": vars.originalPayload.id as String,
    "Email": vars.originalPayload.contact_email default "",
    "ZyrRemarks": vars.originalPayload.note default "",
    "DeliveryModeCode": deliveryMode,
    
    // NEWLY ADDED FIELDS
    "DefaultShippingSiteId": "Zyris",
    "DefaultShippingWarehouseId": "Zyris",
    
    ("DeliveryAddressLocationId": vars.locationIdMap[vars.selectedCustomerAccount as String]) if (vars.locationIdMap[vars.selectedCustomerAccount as String] != null),
    
    "ZyrTaxAmount": (vars.originalPayload.total_tax default 0) as Number {class: "java.math.BigDecimal"},
    "ZyrFreightAmount": (vars.originalPayload.total_shipping_price_set.shop_money.amount default 0) as Number {class: "java.math.BigDecimal"},
    "ZyrShipRatesCalculated": {
        "muleAdditions": {
            "kind": "enum",
            "type": "Microsoft.Dynamics.DataEntities.NoYes"
        },
        "value": "Yes"
    },
    
    "SalesOrderOriginCode": "SHOPIFY",
    
    "ZyrPaymMode": paymentMethod,
    
    "PaymentTermsName": paymentTerms,
    "SkipCreateAutoCharges": {
        "muleAdditions": {
            "kind": "enum",
            "type": "Microsoft.Dynamics.DataEntities.NoYes"
        },
        "value": "Yes"
    }
}

%dw 2.0
output application/json

// Find the capture transaction
var captureTx = (payload.transactions filter ((t) -> lower(t.kind) == "capture"))[0] default null

// Extract based on Gateway rules
var txId = if (captureTx != null and lower(captureTx.gateway) == "paypal") 
               captureTx.authorization
           else if (captureTx != null) 
               captureTx.payment_id
           else ""
---
{
    "ZyrTransactionId": txId
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java

var accountsWithOrders = vars.accountStats filter ($.hasOrders == true)

---
if (sizeOf(accountsWithOrders) > 0 and sizeOf(accountsWithOrders) < sizeOf(vars.accountStats))
    // ORD-004: Mixed - pick first account WITH order history
    accountsWithOrders[0].accountId
else
    // ORD-005: All or None - pick oldest account by ID ascending
    (vars.accountStats orderBy $.accountId)[0].accountId

