%dw 2.0
output application/json
---
{
  "properties": {
    "hs_pipeline": "877239909",
    "hs_pipeline_stage": "1315575349",
    "subject": "Manual Review Required - Shopify Order " ++ (vars.originalPayload.name default ""),
    "content": "A Quote was generated in D365 due to ORD rules. Quotation Number: " ++ (vars.d365QuotationNumber default "")
  }
