%dw 2.0 output application/json
var ship = vars.originalPayload.shipping_address default {} var bill = vars.originalPayload.billing_address default {} var cust = vars.originalPayload.customer default {}
// Fallback to customer name if company is blank var defaultName = (cust.first_name default "") ++ " " ++ (cust.last_name default "")
--- { "dataAreaId": "zyus", "PartyType": "Organization", "CustomerGroupId": "Retail", "SalesTaxGroup": "AVATAX", "PaymentMethod": "CREDITCARD", "PaymentTerms": "CREDITCARD", "SalesCurrencyCode": "USD", "SiteId": "Zyris", "WarehouseId": "Zyris", "OrganizationName": bill.company default defaultName,
// Primary Contacts consolidated "PrimaryContactEmail": vars.originalPayload.email default cust.email default "", "PrimaryContactPhone": (vars.originalPayload.phone default cust.phone default "") replace "+" with "",
// Delivery Address consolidated "DeliveryAddressDescription": "Ship to", "DeliveryAddressStreet": (ship.address1 default "") ++ " " ++ (ship.address2 default ""), "DeliveryAddressCity": ship.city default "", "DeliveryAddressState": ship.province_code default "", "DeliveryAddressCountryRegionId": "USA", "DeliveryAddressCountryRegionISOCode": "US", "DeliveryAddressZipCode": ship.zip default "",
// Invoice Address consolidated "InvoiceAddressDescription": "Bill to", "InvoiceAddressStreet": (bill.address1 default "") ++ " " ++ (bill.address2 default ""), "InvoiceAddressCity": bill.city default "", "InvoiceAddressState": bill.province_code default "", "InvoiceAddressCountryRegionId": "USA", "InvoiceAddressCountryRegionISOCode": "US", "InvoiceAddressZipCode": bill.zip default "",
"PaymentTerms": "CREDITCARD", "PaymentMethod": "CREDITCARD", "SalesCurrencyCode": "USD" }
